import json
with open('/home/shulin/.openclaw/workspace/session-backups/2d1c5558-41b0-453e-8d20-d07659312d4a.jsonl') as f:
    for i, line in enumerate(f):
        obj = json.loads(line)
        t = obj.get('type')
        if t == 'session':
            print(f'[{i}] type=session, id={obj.get(\"id\")}, ts={obj.get(\"timestamp\")}')
        elif t == 'message':
            role = obj.get('role')
            msg = obj.get('message','')
            if isinstance(msg, dict):
                text = msg.get('text','') or ''
                for part in msg.get('content', []):
                    if isinstance(part, dict) and part.get('type') == 'text':
                        text += part.get('text','')
            else:
                text = str(msg)
            print(f'[{i}] type=message, role={role}, text={text[:200]}')
        else:
            print(f'[{i}] type={t}')
" 2>&1

